import{_ as t,c as a,a1 as o,o as r}from"./chunks/framework.nlCHK0Xf.js";const n="/16.jpg",i="/17.jpg",p=JSON.parse('{"title":"Use Mipi Camera","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"starter/7 Use Mipi Camera.md","filePath":"starter/7 Use Mipi Camera.md"}'),c={name:"starter/7 Use Mipi Camera.md"};function s(u,e,l,h,d,f){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="use-mipi-camera" tabindex="-1">Use Mipi Camera <a class="header-anchor" href="#use-mipi-camera" aria-label="Permalink to &quot;Use Mipi Camera&quot;">​</a></h1><p>The Puffin board supports MIPI camera modules, allowing you to capture high-quality images and videos for your projects. This section will guide you through the process of connecting a MIPI camera to your Puffin board and accessing the camera feed.</p><h3 id="_1-connect-the-mipi-camera" tabindex="-1">1.Connect the MIPI camera <a class="header-anchor" href="#_1-connect-the-mipi-camera" aria-label="Permalink to &quot;1.Connect the MIPI camera&quot;">​</a></h3><p>Locate the MIPI camera interface on your Puffin board. Take the MIPI camera module and identify the flex cable attached to it. Ensure that the cable is oriented correctly and fully seated in the connector. <img src="'+n+'" alt="Puffin connector"></p><h3 id="_2-accessing-the-camera-feed" tabindex="-1">2.Accessing the Camera Feed <a class="header-anchor" href="#_2-accessing-the-camera-feed" aria-label="Permalink to &quot;2.Accessing the Camera Feed&quot;">​</a></h3><p>Log in to your account on www.wirelessx.io. Navigate to your user profile page and locate the registered Puffin module. Click on the &quot;Start&quot; button next to the module. Scroll down to the &quot;Puffin Control Panel&quot; section and click on the &quot;Enter&quot; button. Click on the &quot;Connect&quot; button in the Puffin Control Panel, you will find a video streaming. <img src="'+i+'" alt="Puffin connector"></p><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><p>If you do not see the camera feed in the Puffin Control Panel, double-check the connection of the flex cable to ensure it is properly inserted and oriented correctly. Verify that the Puffin board is powered on and connected to the Puffin Control Panel. If you encounter any further difficulties, refer to the troubleshooting section or reach out to our support team for assistance.</p>',8)]))}const P=t(c,[["render",s]]);export{p as __pageData,P as default};
